import {fromUnits,toUnits,normalizeTransaction,validateAddress,validateMemo,assertRoute} from './funding-catalog.mjs';
export function createFundingService(accounts){
 const client=accounts.client;async function checked(q){const {data,error}=await q;if(error)throw Error(error.code==='23505'?'This transaction or request has already been recorded.':error.message);return data;}
 async function user(){const u=await accounts.user({fresh:true});if(!u)throw Error('Sign in to manage your funds.');return u;}
 const fields='*,amount::text,fee::text';
 async function load(){const u=await user();const [routes,balances,history]=await Promise.all([checked(client.from('funding_routes').select('*,deposit_fee::text')),checked(client.from('wallet_balances').select('asset,available::text,reserved::text').eq('user_id',u.id)),checked(client.from('funding_requests').select(fields).eq('user_id',u.id).order('created_at',{ascending:false}).limit(50))]);const exact=(v,a)=>fromUnits(toUnits(v,a,{allowZero:true}),a);return {routes:routes.map(r=>({...r,deposit_fee:exact(r.deposit_fee,r.asset)})),balances:balances.map(b=>({...b,available:exact(b.available,b.asset),reserved:exact(b.reserved,b.asset)})),history:history.map(r=>({...r,amount:exact(r.amount,r.asset),fee:exact(r.fee,r.asset)}))};}
 async function create(kind,asset,network,amount,id,destination={}){assertRoute(asset,network);if(kind==='withdrawal'){destination={address:validateAddress(network,destination.address),memo:validateMemo(network,destination.memo)};}const u=await user();const value=fromUnits(toUnits(amount,asset),asset);const existing=await checked(client.from('funding_requests').select(fields).eq('id',id).eq('user_id',u.id).maybeSingle());if(existing)return existing;const row=await checked(client.from('funding_requests').insert({id,user_id:u.id,kind,asset,network,amount:value,...(kind==='withdrawal'?destination:{})}).select(fields).single());window.dispatchEvent(new Event('wallet-updated'));return row;}
 async function report(row,hash,index){await user();if(!Number.isSafeInteger(index)||index<0)throw Error('Enter a nonnegative transfer index.');return checked(client.from('funding_requests').update({transaction_hash:normalizeTransaction(row.network,hash),transfer_index:index}).eq('id',row.id).select(fields).single());}
 async function cancel(id){await user();const row=await checked(client.from('funding_requests').update({cancel_requested:true}).eq('id',id).select(fields).single());window.dispatchEvent(new Event('wallet-updated'));return row;}
 return {load,create,report,cancel};
}
